// Standard counted loop: 0, 1, 2, 3, 4
for (int i = 0; i < 5; i++)
{
    Console.WriteLine($"Iteration {i}");
}

// Counting downward
for (int i = 10; i >= 1; i--)
{
    Console.WriteLine($"Countdown: {i}");
}

// Step by 2 (even numbers)
for (int i = 0; i <= 10; i += 2)
{
    Console.WriteLine($"Even: {i}");
}

// Multiple variables in one for loop
for (int i = 0, j = 10; i < j; i++, j--)
{
    Console.WriteLine($"i={i}, j={j}");
}

// Omitting sections (be careful — can create infinite loops)
int k = 0;
for (; k < 3; )
{
    Console.WriteLine($"k = {k}");
    k++; // update must be inside the body
}

string[] colors = { "Red", "Green", "Blue", "Yellow" };

// Iterate array
foreach (string color in colors)
{
    Console.WriteLine(color);
}

// Iterate a List
List<int> scores = new List<int> { 88, 92, 76, 99, 85 };
int total = 0;
foreach (int score in scores)
{
    total += score;
}
Console.WriteLine($"Average: {total / (double)scores.Count}");

// Iterate characters in a string
string message = "Hello C#";
foreach (char c in message)
{
    Console.WriteLine($"Character: '{c}' (ASCII {(int)c})");
}

// Using IndexOf for position (manual approach)
for (int i = 0; i < colors.Length; i++)
{
    Console.WriteLine($"{i}: {colors[i]}");
}

// Count down from 5
int counter = 5;
while (counter > 0)
{
    Console.WriteLine($"{counter}...");
    counter--;
}
Console.WriteLine("Liftoff!");

// User input validation loop
string? input;
int parsedValue;

Console.Write("Enter a positive number: ");
input = Console.ReadLine();

while (!int.TryParse(input, out parsedValue) || parsedValue <= 0)
{
    Console.WriteLine("Invalid input. Please enter a positive integer.");
    Console.Write("Try again: ");
    input = Console.ReadLine();
}
Console.WriteLine($"You entered: {parsedValue}");

// Reading until a sentinel value
int sum = 0;
int value;
Console.WriteLine("Enter numbers (0 to stop):");
value = int.Parse(Console.ReadLine());
while (value != 0)
{
    sum += value;
    value = int.Parse(Console.ReadLine());
}
Console.WriteLine($"Total: {sum}");

// Simple menu that runs at least once
string? choice;
do
{
    Console.WriteLine("\n--- Menu ---");
    Console.WriteLine("1. Say Hello");
    Console.WriteLine("2. Show Date");
    Console.WriteLine("3. Exit");
    Console.Write("Choose an option: ");
    choice = Console.ReadLine();

    switch (choice)
    {
        case "1":
            Console.WriteLine("Hello, learner!");
            break;
        case "2":
            Console.WriteLine(DateTime.Now.ToShortDateString());
            break;
        case "3":
            Console.WriteLine("Goodbye!");
            break;
        default:
            Console.WriteLine("Invalid option.");
            break;
    }

} while (choice != "3");

// Password prompt that always asks at least once
string? password;
do
{
    Console.Write("Enter password: ");
    password = Console.ReadLine();
} while (password != "secret");
Console.WriteLine("Access granted!");

// break: stop at the first match
int[] numbers = { 4, 8, 15, 16, 23, 42 };
int target = 23;

for (int i = 0; i < numbers.Length; i++)
{
    if (numbers[i] == target)
    {
        Console.WriteLine($"Found {target} at index {i}");
        break; // exit loop immediately
    }
}

// continue: skip negative numbers
int[] values = { 5, -3, 8, -1, 10, -7, 4 };
int positiveSum = 0;

foreach (int v in values)
{
    if (v < 0)
    {
        continue; // skip to next iteration
    }
    positiveSum += v;
}
Console.WriteLine($"Sum of positives: {positiveSum}"); // 27

// break in a do-while menu
string? menuChoice;
do
{
    Console.Write("Enter command (or 'quit' to exit): ");
    menuChoice = Console.ReadLine();
    if (menuChoice == "quit")
    {
        break; // exit the loop
    }
    Console.WriteLine($"You typed: {menuChoice}");
} while (true);

// Multiplication table: 5 rows x 5 columns
for (int row = 1; row <= 5; row++)
{
    for (int col = 1; col <= 5; col++)
    {
        int product = row * col;
        Console.Write($"{product,4}"); // padded to 4 spaces
    }
    Console.WriteLine(); // new line after each row
}

